/**
 * Machine-readable reason of onboard_error. Clients localize by reason, never by message text.
 * Waiting device side (every app platform: iPhone, iPad, Apple TV, Apple Watch through its
 * iPhone and the Android counterparts): invalid_request = public_key/client_name missing or
 * malformed; invalid_client_info = malformed client info; platform_not_supported = this client
 * cannot be set up by another device (web); tls_required = onboard_start over the cleartext
 * port (TLS :8100 with the pinned fingerprint is mandatory); rate_limited = start limit of
 * this source IP reached; already_authenticated = the connection is already authenticated;
 * connection_expired = the connection was evicted; session_expired = the 5-minute window has
 * passed (the hub closes 4002 right after); session_invalidated = a confirmation carried
 * another public key or hub id than the session (possible man in the middle), the session is
 * gone; declined = the confirming device declined; cancelled = an admin cancelled the session.
 * Confirming device side additionally: session_not_found = unknown, used, expired or cancelled
 * session id or code (“Code not found”); hub_mismatch = the QR code belongs to another hub;
 * not_permitted = this device may not set up devices (effective rule setup_devices off:
 * guests, parental controls, a profile that is not of kind person, or not allowed by profile
 * or adjustment; a watch additionally needs the rule watch); too_many_attempts = too many
 * wrong codes from this device or on the hub (x-limits onboard_code_*; scan the QR code or
 * wait); rate_limited = failure limit of this device reached; kind_not_allowed = the kind is
 * not in setup_devices.kinds of this device or does not fit the platform of the waiting device
 * (also in onboard_lookup when no allowed kind fits it); profile_not_allowed = the profile is
 * not offered for this kind (onboard_info.grant): unknown, another kind, stronger than the
 * rights of the confirming device, or not allowed on the platform of the new device
 * (docs/setup.md, Platform of the profile); areas_not_allowed = the area choice is empty,
 * names an unknown or inactive area, an area the confirming device does not see itself, or
 * all_areas although the confirming device does not see all areas; also an own_area_id or
 * start_area outside grant.areas; expiry_not_allowed = a guest, house sitter or babysitter
 * without expires_at, in the past or more than 90 days ahead (guest_access.max_hours), or an
 * expiry for another kind; managers_not_allowed = managers sent without the right
 * family_manager, or a device that is no family manager; access_hours_not_allowed =
 * access_windows sent although the grant does not offer access hours for the profile
 * (access_hours_choice false: the profile fixes the rule access_hours); device_not_found =
 * set_up_device_remove names no active device set up by this device. Validation errors of
 * onboard_confirm (kind_not_allowed, profile_not_allowed, areas_not_allowed,
 * expiry_not_allowed, managers_not_allowed, access_hours_not_allowed) keep the session open
 * and count as a failed attempt. Clients must treat an unknown reason like session_not_found
 * (show a new code / scan again).
 */
export type OnboardErrorReason = "invalid_request" | "invalid_client_info" | "tls_required" | "rate_limited" | "already_authenticated" | "connection_expired" | "session_not_found" | "session_expired" | "session_invalidated" | "hub_mismatch" | "not_permitted" | "declined" | "cancelled" | "platform_not_supported" | "areas_not_allowed" | "too_many_attempts" | "kind_not_allowed" | "profile_not_allowed" | "expiry_not_allowed" | "managers_not_allowed" | "device_not_found" | "access_hours_not_allowed";
export const ONBOARD_ERROR_REASON_VALUES: readonly OnboardErrorReason[] = ["invalid_request", "invalid_client_info", "tls_required", "rate_limited", "already_authenticated", "connection_expired", "session_not_found", "session_expired", "session_invalidated", "hub_mismatch", "not_permitted", "declined", "cancelled", "platform_not_supported", "areas_not_allowed", "too_many_attempts", "kind_not_allowed", "profile_not_allowed", "expiry_not_allowed", "managers_not_allowed", "device_not_found", "access_hours_not_allowed"];

/**
 * How an onboarding session ended: confirmed, declined (by the confirming device), expired,
 * cancelled (admin), invalidated (key or hub mismatch), replaced (new code on the same
 * connection), disconnected (the waiting device closed the connection).
 */
export type OnboardingResult = "confirmed" | "declined" | "expired" | "cancelled" | "invalidated" | "replaced" | "disconnected";
export const ONBOARDING_RESULT_VALUES: readonly OnboardingResult[] = ["confirmed", "declined", "expired", "cancelled", "invalidated", "replaced", "disconnected"];

/**
 * Machine-readable reason of pair_error. Clients localize by reason, never by message text
 * (English, for logs only). invalid_request = pin/client_name missing, not strings or
 * client_name longer than 100 characters; invalid_client_info = malformed client info;
 * pin_invalid = no active PIN matches (wrong, already used or cancelled); pin_expired = the
 * PIN matched but its 5-minute window has passed; too_many_failures = the PIN matched but was
 * invalidated after too many failed attempts (ask the admin for a new PIN); rate_limited =
 * attempt limit of this connection or source IP reached (reconnect / try again later);
 * already_authenticated = the connection is already authenticated; connection_expired = the
 * connection was evicted, reconnect; platform_not_allowed = the profile the PIN gives is not
 * allowed on the platform the device reports (docs/setup.md, Platform of the profile): ask the
 * admin for a PIN with another profile. Clients must treat an unknown reason like pin_invalid.
 */
