/**
 * A running early access of a device – a Yes to its request (or the admin) opened it before
 * its access hours allow. Only the schedule part: the access switch still applies. The hub
 * deletes it at until; until is never in the past while it is shown.
 */
export interface AccessEarly {
  /** End of the early access (UTC). */
  until: string;
  by: AccessRequestActor;
  request_id: string | null;
  duration?: AccessRequestDuration | null;
  /** When it was granted. */
  at: string;
}

/**
 * Value of the profile rule access_hours (“Access hours”, docs/access.md): enabled = the
 * device has access only inside the windows; outside it stays paired but sees nothing (no
 * areas, no states, no control) and only shows when access opens again. enabled false = no
 * time limit (the access switch still applies). enabled with no window = no access at all.
 */
export interface AccessHours {
  enabled: boolean;
  windows: AccessWindow[];
}

/**
 * Access of a device right now (docs/access.md): open = access hours (when enabled) allow now
 * AND the access switch (when the device has one) is on. Computed by the hub in Home
 * Assistant's time zone; reference tools/access_ref.py, vectors
 * fixtures/profiles/access-hours. The app shows only “Access again from …” while open is
 * false. early = a running early access (a Yes to the device's request): open while the switch
 * allows it, until follows the early access and the windows that continue it.
 */
export interface AccessNow {
  open: boolean;
  /** Only while closed; null while open. */
  reason: AccessClosedReason | null;
  /**
   * Open: end of the running access window (windows that touch are followed to their common
   * end); null = open without a time limit (no access hours). Closed: null.
   */
  until: string | null;
  /**
   * Closed by the schedule with the switch on: start of the next window (within 8 days). null
   * while open, while the switch is off (nobody knows when it is switched on again) and when no
   * window comes.
   */
  opens_at: string | null;
  /** The effective rule access_hours is enabled. */
  schedule: boolean;
  /**
   * State of the device's access switch; null = the device has no switch (no access hours and
   * not of kind guest, house_sitter or babysitter).
   */
  switch: boolean | null;
  /**
   * Running early access (until in the future), null or missing = none. While it runs, open is
   * true unless the switch is off; until is the end of the early access or of the windows that
   * follow it directly.
   */
  early?: AccessEarly | null;
}

/**
 * A device outside its access hours asks for access now. One open request per device. answer
 * is set exactly for approved/declined. The requesting device sees status, answer (answer,
 * duration, until, message, by.name) and recipients; recipients and the admin also see the
 * device and its note. Times in UTC. tools/validate.py checks that answer is an object exactly
 * for approved and declined.
 * Schema: schemas/common/access-request.json
 */
export interface AccessRequest {
  request_id: string;
  client_id: string;
  device_name: string;
  owner_label?: string | null;
  profile_kind?: ProfileKind;
  note?: string | null;
  status: AccessRequestStatus;
  created_at: string;
  expires_at: string;
  opens_at: string | null;
  /**
   * Durations a Yes may give for this request (until_window_start only with a known opens_at at
   * most until_window_start_max_hours ahead).
   */
  durations: AccessRequestDuration[];
  recipients: AccessRequestRecipientsItem[];
  /** Only in the copy for a recipient device: it may answer now. */
  can_answer?: boolean;
  answer: AccessRequestAnswer | null;
}

/**
 * Who opened a device early or answered its request: device = a recipient device (set up the
 * device, may set up its kind, or a family manager for a babysitter); admin = the admin UI;
 * hub = the hub (expiry). Names are display names at that time; never HA user ids, tokens or
 * IP addresses.
 */
export interface AccessRequestActor {
  kind: AccessRequestActorKind;
  client_id: string | null;
  /** Owner label (first name) of the device, else its name; admin display name for admin. */
  name: string;
  owner_label?: string | null;
  via?: FamilyRoute | null;
}

export interface AccessRequestAnswer {
  answer: FamilyAnswer;
  duration?: AccessRequestDuration | null;
  until?: string | null;
  message?: AccessDeclineMessage | null;
  by: AccessRequestActor;
  at: string;
}

/**
 * “Ask for early access” on the requesting device; present exactly while the effective rule
 * access_requests is on. enabled = the rule is on and the device has access hours; available =
 * it can ask right now: enabled, closed by the schedule (access.hours.reason schedule, switch
 * on), no own open request, limits not reached and someone can answer (recipients or an admin
 * notification rule for access_requested). The app shows the button on “Access again from …”
 * only with available; requests go only over the hub WebSocket (at home: away the device holds
 * no valid Home Assistant key while closed, the app says “Only possible at home”). The hub
 * sends client_config_updated when available, recipients or the open request change.
 * Schema: schemas/common/access-request-config.json
 */
export interface AccessRequestConfig {
  enabled: boolean;
  available: boolean;
  open: AccessRequest | null;
  next_allowed_at: string | null;
  /**
   * Who gets a request now, for “Mum and Dad will get your request.”: the device that set it up
   * first, then the devices that may set up its kind and (babysitter) the family managers, by
   * name; each name once. Empty with available true = only the admin is notified.
   */
  recipients: AccessRequestConfigRecipientsItem[];
}

export interface AccessRequestConfigRecipientsItem {
  /** First name (owner label), else the device name. */
  name: string;
  role: AccessRequestRole;
}

export interface AccessRequestRecipientsItem {
  /** First name (owner label), else the device name. */
  name: string;
  role: AccessRequestRole;
}

/**
 * Window of the rule access_hours in the hub time zone (Home Assistant's time_zone): the
 * device has access from start to end on the listed days. Same form as a bedtime window: end
 * <= start crosses midnight and belongs to the start day (fri 18:00-01:00 ends Saturday
 * 01:00); start == end = 24 hours from start. Windows that touch or overlap are one continuous
 * access.
 */
export interface AccessWindow {
  days: KidsWeekday[];
  start: string;
  end: string;
}

