/**
 * k_sign = HMAC_SHA256(key=digest32, msg=label); sig = hexlower(HMAC_SHA256(key=k_sign,
 * msg='v1|'+client_id+'|'+status+'|'+ts)). digest32 = raw SHA-256 of the UTF-8 client secret.
 * Recomputed by tools/validate.py.
 * Schema: schemas/crypto/compliance-vectors.json
 */
export interface CryptoComplianceVectors {
  /** Functional label, independent of brand and namespace. */
  label: "hub/compliance/v1";
  cases: CryptoComplianceVectorsCasesItem[];
}

export interface CryptoComplianceVectorsCasesItem {
  /** Optional; when present digest32 = sha256(secret). */
  secret?: string;
  digest32?: string;
  client_id: string;
  status: CryptoComplianceVectorsCasesItemStatus;
  ts: number;
  k_sign: string;
  sig: string;
}

/**
 * onboard_ok.sealed: HPKE base mode (RFC 9180) DHKEM(X25519, HKDF-SHA256), HKDF-SHA256,
 * ChaCha20Poly1305, sequence number 0. Case rfc9180-a.2.1-seq0 is the RFC test vector A.2.1
 * (first encryption); case onboard-v1 uses info "hub/onboard/v1", aad = session id (ASCII) and
 * the plaintext JSON {client_id, secret}; case watch-access-v1 uses info
 * "hub/watch-access/v1", aad = client_id (ASCII) and a sealed watch access
 * (crypto/watch-access-plaintext.json, watch_access.sealed). tools/validate.py recomputes enc
 * and ct from sk_e and checks that sk_r opens ct; the hub and the apps (CryptoKit
 * HPKE.Recipient) open every case.
 * Schema: schemas/crypto/onboard-seal-vectors.json
 */
export interface CryptoOnboardSealVectors {
  suite: "X25519-SHA256-ChaCha20Poly1305";
  kem_id: 32;
  kdf_id: 1;
  aead_id: 3;
  mode: 0;
  cases: CryptoOnboardSealVectorsCasesItem[];
}

export interface CryptoOnboardSealVectorsCasesItem {
  name: string;
  sk_r: string;
  pk_r: string;
  sk_e: string;
  enc: string;
  info: string;
  aad: string;
  pt: string;
  ct: string;
}

/**
 * hash = hex(PBKDF2-HMAC-SHA256(password=utf8(pin), salt=bytes.fromhex(salt), iterations,
 * dkLen)). Recomputed by tools/validate.py.
 * Schema: schemas/crypto/settings-pin-vectors.json
 */
export interface CryptoSettingsPinVectors {
  algorithm: "PBKDF2-HMAC-SHA256";
  iterations: 100000;
  dklen: 32;
  cases: CryptoSettingsPinVectorsCasesItem[];
}

export interface CryptoSettingsPinVectorsCasesItem {
  pin: string;
  salt: string;
  hash: string;
}

/**
 * What watch_access.sealed carries once the watch opened it. config is the watch's own
 * client_config (with its HA token; null only while it has none, e.g. outside its access
 * hours: the watch then keeps its stored token and applies the rest). The watch checks that
 * client_id equals the outer client_id and its own, and ignores an issued_at older than the
 * access it holds (a replayed message never replaces a newer one).
 * Schema: schemas/crypto/watch-access-plaintext.json
 */
export interface CryptoWatchAccessPlaintext {
  client_id: string;
  /** When the hub sealed it (UTC, ISO 8601 with milliseconds). */
  issued_at: string;
  config: ClientConfig;
}

