  notifications: DataProfileRulesNotifications;
  /**
   * Safety entities: notifications about them are never suppressed; with parental controls they
   * are always visible read-only (controlling the alarm stays blocked); “When away” is at least
   * view for them. No delivery promise: no push, the app shows them while open; the product is
   * no alarm system.
   */
  safety_entities: DataProfileRulesSafetyEntities;
