/**
 * Asks the integration to make sure the device has its own HA user with exactly one long-lived
 * access token and to deliver that token via POST /api/integration/client-token. Sent as WS
 * push provision_client and repeated in GET /api/integration/status provisioning[] until the
 * hub has the token. Handling MUST be idempotent: token_action=ensure reuses the device's
 * existing token (a new access token is derived from the same refresh token, refresh_token_id
 * stays the same); only token_action=rotate mints a new one.
 * Schema: schemas/common/provision-request.json
 */
export interface ProvisionRequest {
  client_id: string;
  display_name: string;
  owner_label?: string | null;
  is_guest: boolean;
  /**
   * Device may use HA from outside the local network: the effective profile rule remote_access.
   * Default false (local-first); also for guests when their profile allows it and for devices
   * with parental controls (read-only key, docs/enforcement.md §7).
   */
  remote_allowed: boolean;
  /**
   * Guest expiry (UTC). The integration bounds the HA-side token lifetime to expiry + 7 days
   * grace and rotates the token when an extension is no longer covered.
   */
  guest_expires_at?: string | null;
  /** Correlation id for logs; not used for deduplication. */
  request_id?: string;
  /**
   * ensure: create user/token if missing, otherwise re-deliver the current token. rotate: mint a
   * new token for the same user; the integration removes the old one only after the hub
   * acknowledged the new one.
   */
  token_action: ProvisionRequestTokenAction;
  /**
   * Why the hub asks (logging, UI). pair = newly paired device (status pending); retry = earlier
   * request unanswered; rotate = admin rotate-token; guest_extend = guest extended beyond the
   * token lifetime; reprovision = the hub has no usable token for an active device (e.g.
   * restored backup).
   */
  reason: ProvisionRequestReason;
}

